	Companion Functions
-------------------------------------------]]
-- Conquest of Azeroth / Ascension: the vanity collections hold some companions that never return a
-- name (21 of 861 mounts here), and aborting on the first one meant the cache - and with it Button
-- Forge's whole start-up - never completed (ButtonForgeSave stayed nil). Nameless entries are now
-- skipped; the cache is only left for a later retry while most names are still missing (data not
-- loaded yet), which is what the original early return was for.
local function CacheCompanionType(Type, Cache)
    local Total, Missing = GetNumCompanions(Type), 0;
    for i = 1, Total do
        local Id, Name = GetCompanionInfo(Type, i);
		if (Name) then
			Cache[Name] = i;
		else
			Missing = Missing + 1;
		end
    end
	return Total == 0 or Missing * 2 < Total;
end

function Util.CacheCompanions()
    Util.Critters = {};
    if (not CacheCompanionType("CRITTER", Util.Critters)) then
		return;
	end

    Util.Mounts = {};
    if (not CacheCompanionType("MOUNT", Util.Mounts)) then
		return;
	end
	Util.CompanionsCached = true;
end
